import { requireShowcaseTestRoutes } from "@/lib/testRouteAccess";
import { createSupabaseServerClient } from "@/lib/supabaseServer";
import { redirect } from "next/navigation";

type TestResult = {
  ok: boolean;
  stage?: string;
  error?: string;
  details?: unknown;
};

async function runZ5AuthorizationTest() {
  "use server";

  requireShowcaseTestRoutes();
  const supabase = await createSupabaseServerClient();

  const {
    data: { user },
    error: userError,
  } = await supabase.auth.getUser();

  if (userError || !user) {
    redirect(
      `/z5-authorize-test?result=${encodeURIComponent(
        JSON.stringify({
          ok: false,
          stage: "authentication",
          error: userError?.message ?? "No authenticated user",
        } satisfies TestResult)
      )}`
    );
  }

  const actorId = user.id;
  const operationId = crypto.randomUUID();

  let result: TestResult;

  try {
    // ------------------------------------------------------------
    // 1. Create a fresh proposal.
    // ------------------------------------------------------------
    const { data: proposalData, error: proposalError } =
      await supabase.rpc("create_proposal", {
        target_change_id: `Z5 authorization release test ${operationId}`,
        target_scope: "Synthetic Z5 authorization boundary verification",
        target_affected_system: "judgment-engine-test",
        target_environment: "sandbox",
        target_decision_class: "ai_system_change_approval",
        target_assumptions:
          "Synthetic test. No external action will be performed.",
        target_alternatives: [
          "Authorize the synthetic operation",
          "Reject the synthetic operation",
        ],
        target_evidence: [
          "Z5 authorization-release integration test",
        ],
        target_known_risks:
          "No external side effect; authorization is the only intended outcome.",
      });

    if (proposalError) {
      throw new Error(`create_proposal failed: ${proposalError.message}`);
    }

    const proposal = Array.isArray(proposalData)
      ? proposalData[0]
      : proposalData;

    if (!proposal?.review_cycle_id) {
      throw new Error("create_proposal returned no review_cycle_id");
    }

    const reviewCycleId = proposal.review_cycle_id;

    // ------------------------------------------------------------
    // 2. Assign the authenticated actor as decision-maker.
    // ------------------------------------------------------------
    const { error: decisionMakerError } = await supabase.rpc(
      "assign_review_cycle_decision_maker",
      {
        target_review_cycle_id: reviewCycleId,
        target_decision_maker_actor_id: actorId,
      }
    );

    if (decisionMakerError) {
      throw new Error(
        `assign_review_cycle_decision_maker failed: ${decisionMakerError.message}`
      );
    }
    // ------------------------------------------------------------
    // 2. Assign the authenticated actor as reviewer.
    // ------------------------------------------------------------
    const { error: reviewerError } = await supabase.rpc(
      "assign_review_cycle_reviewer",
      {
        target_review_cycle_id: reviewCycleId,
        target_reviewer_actor_id: actorId,
      }
    );

    if (reviewerError) {
      throw new Error(
        `assign_review_cycle_reviewer failed: ${reviewerError.message}`
      );
    }

    // ------------------------------------------------------------
    // 3. Create the structured Judgment Draft.
    // ------------------------------------------------------------
    const { data: draftData, error: draftError } = await supabase.rpc(
      "create_judgment_draft_for_review_cycle",
      {
        target_review_cycle_id: reviewCycleId,
      }
    );

    if (draftError) {
      throw new Error(
        `create_judgment_draft_for_review_cycle failed: ${draftError.message}`
      );
    }

    const draft = Array.isArray(draftData) ? draftData[0] : draftData;

    if (!draft?.judgment_draft_id) {
      throw new Error(
        "create_judgment_draft_for_review_cycle returned no judgment_draft_id"
      );
    }

    // ------------------------------------------------------------
    // 4. Confirm the Judgment as the assigned reviewer.
    // ------------------------------------------------------------
    const { data: confirmationData, error: confirmationError } =
      await supabase.rpc("confirm_review_cycle_judgment", {
        target_review_cycle_id: reviewCycleId,
        target_reconsideration_conditions:
          "Reassess if the execution authorization boundary changes.",
        target_predecessor_judgment_id: null,
        target_is_supersession: false,
        target_supersession_rationale: null,
        target_validation_basis: null,
      });

    if (confirmationError) {
      throw new Error(
        `confirm_review_cycle_judgment failed: ${confirmationError.message}`
      );
    }

    const confirmation = Array.isArray(confirmationData)
      ? confirmationData[0]
      : confirmationData;

    if (!confirmation?.judgment_id) {
      throw new Error(
        "confirm_review_cycle_judgment returned no judgment_id"
      );
    }


    // ------------------------------------------------------------
    // 6. Record the approval decision.
    // ------------------------------------------------------------
    const decisionCorrelationId = crypto.randomUUID();
    const decisionCausationId = confirmation.judgment_id;

    const { data: decisionData, error: decisionError } = await supabase.rpc(
      "record_review_decision",
      {
        target_review_cycle_id: reviewCycleId,
        target_decision: "approve",
        target_authority_basis:
          "Synthetic Z5 authorization-release integration test",
        target_rationale:
          "Synthetic approval used only to verify the JE authorization boundary.",
        target_residual_risks:
          "No external action is executed by this test.",
        target_correlation_id: decisionCorrelationId,
        target_causation_id: decisionCausationId,
      }
    );

    if (decisionError) {
      throw new Error(
        `record_review_decision failed: ${decisionError.message}`
      );
    }

    const decisionRow = Array.isArray(decisionData)
      ? decisionData[0]
      : decisionData;

    if (!decisionRow?.decision_id) {
      throw new Error(
        "record_review_decision returned no decision_id"
      );
    }

    if (decisionRow.decision !== "approve") {
      throw new Error(
        `Expected approve decision, received ${decisionRow.decision}`
      );
    }

    // ------------------------------------------------------------
    // 7. Issue execution authority with complete Z3 binding.
    // ------------------------------------------------------------
    const action = "z5_authorization_release_test";
    const scope = "Synthetic Z5 authorization boundary verification";
    const target = `synthetic:z5:${operationId}`;
    const parameters = {
      test_case: "successful_authorization_release",
      operation_id: operationId,
    };

    const validFrom = new Date(Date.now() - 60_000).toISOString();
    const validUntil = new Date(Date.now() + 10 * 60_000).toISOString();

    const { data: authorityData, error: authorityError } =
      await supabase.rpc("issue_execution_authority", {
        target_decision_id: decisionRow.decision_id,
        target_action: action,
        target_scope: scope,
        target_target: target,
        target_parameters: parameters,
        target_valid_from: validFrom,
        target_valid_until: validUntil,
      });

    if (authorityError) {
      throw new Error(
        `issue_execution_authority failed: ${authorityError.message}`
      );
    }

    const authority = Array.isArray(authorityData)
      ? authorityData[0]
      : authorityData;

    if (!authority?.authority_id) {
      throw new Error(
        "issue_execution_authority returned no authority_id"
      );
    }

    // ------------------------------------------------------------
    // 8. Release authorization for the stable operation.
    // ------------------------------------------------------------
    const { data: authorizationData, error: authorizationError } =
      await supabase.rpc("authorize_execution", {
        target_authority_id: authority.authority_id,
        target_action: action,
        target_scope: scope,
        target_operation_id: operationId,
        target_target: target,
        target_parameters: parameters,
      });

    if (authorizationError) {
      throw new Error(
        `authorize_execution failed: ${authorizationError.message}`
      );
    }

    const authorization = Array.isArray(authorizationData)
      ? authorizationData[0]
      : authorizationData;

    if (!authorization) {
      throw new Error("authorize_execution returned no result");
    }

    // ------------------------------------------------------------
    // 9. Verify the release envelope.
    // ------------------------------------------------------------
    const envelopeChecks = {
      status: authorization.status === "authorized",
      authorized: authorization.authorized === true,
      authority_id:
        authorization.authority_id === authority.authority_id,
      decision_id: authorization.decision_id === decisionRow.decision_id,
      actor_id: authorization.actor_id === actorId,
      operation_id: authorization.operation_id === operationId,
      action: authorization.action === action,
      scope: authorization.scope === scope,
      target: authorization.target === target,
      parameters:
        JSON.stringify(authorization.parameters) ===
        JSON.stringify(parameters),
      attempt_id: authorization.attempt_id === null,
      rejection_reason: authorization.rejection_reason === null,
    };

    const envelopePassed = Object.values(envelopeChecks).every(Boolean);

    if (!envelopePassed) {
      throw new Error(
        `Authorization envelope verification failed: ${JSON.stringify(
          envelopeChecks
        )}`
      );
    }

    // ------------------------------------------------------------
    // 10. Critical Z5 boundary check:
    //     authorization must NOT create execution evidence.
    // ------------------------------------------------------------
    const { data: evidenceRows, error: evidenceError } = await supabase
      .from("execution_evidence")
      .select("id, authority_id, operation_id, result")
      .eq("authority_id", authority.authority_id)
      .eq("operation_id", operationId);

    if (evidenceError) {
      throw new Error(
        `Execution evidence verification failed: ${evidenceError.message}`
      );
    }

    if ((evidenceRows ?? []).length !== 0) {
      throw new Error(
        `Z5 boundary violation: authorization created execution evidence: ${JSON.stringify(
          evidenceRows
        )}`
      );
    }

    // ------------------------------------------------------------
    // Z5 SUCCESS
    // ------------------------------------------------------------
    result = {
      ok: true,
      stage: "Z5 authorization-release success path",
      details: {
        actor_id: actorId,
        review_cycle_id: reviewCycleId,
        judgment_id: confirmation.judgment_id,
        decision_id: decisionRow.decision_id,
        authority_id: authority.authority_id,
        operation_id: operationId,
        authorization,
        execution_evidence_rows: evidenceRows ?? [],
        boundary:
          "JE released authorization. No execution evidence was created.",
      },
    };

  } catch (error) {
    result = {
      ok: false,
      stage: "Z5 authorization-release success path",
      error:
        error instanceof Error ? error.message : "Unknown Z5 test failure",
    };
  }

  redirect(
    `/z5-authorize-test?result=${encodeURIComponent(
      JSON.stringify(result)
    )}`
  );
}

